      "error_type": "数值单位错误",
      "spans": [
        {
          "text": "归母净利润为15.7亿分，同比增长384.5%。"
        }
      ],
      "reason": "净利润单位写成“亿分”，应为“亿元”，单位量纲错误。"
    },
    {
      "error_type": "语义逻辑矛盾",
      "spans": [
        {
          "text": "公司受益于数据中心快速发展，营收同比大幅降低。"
        }
      ],
      "reason": "前面已述2025Q1营收同比增长264.1%，此处称“大幅降低”与事实相反。"
    },
    {
      "error_type": "冗余语句",
      "spans": [
        {
          "text": "泰国工厂二期已于2025年初投入运营，目前处于持续扩产阶段，产能储备充分。"
        }
      ],
      "reason": "该句在原文中连续出现两次，属于不必要重复。"
    },
    {
      "error_type": "数值缺失",
      "spans": [
        {
          "text": "国内业务、国外业务毛利率分别为41.69%、 ，同比+16.37pct、+13.45pct。"
        }
      ],
      "reason": "国外业务毛利率明确位置为空，只写了“41.69%、 ”后缺少数值。"
    },
    {
      "error_type": "术语误用",
      "spans": [
        {
          "text": "其中，销售费用率、管理费用率、债权费用率分别-0.91pct、-1.09pct、+1.05pct。"
        }
      ],
      "reason": "“债权费用率”不是标准财务术语，应表述为“财务费用率”。"
    }
  ]
}
